// src/store/slices/emergencySlice.ts
// Aetherion Health - Emergency Redux Slice
// ============================================

import { createSlice, createAsyncThunk, PayloadAction } from '@reduxjs/toolkit';

// ============================================
// TYPES
// ============================================

export type EmergencyType = 
  | 'cardiac' 
  | 'accident' 
  | 'stroke' 
  | 'breathing' 
  | 'bleeding' 
  | 'allergy' 
  | 'pregnancy' 
  | 'other';

export type EmergencyStatus = 
  | 'pending' 
  | 'dispatched' 
  | 'en-route' 
  | 'arrived' 
  | 'picked-up' 
  | 'at-hospital' 
  | 'completed' 
  | 'cancelled';

export interface EmergencyLocation {
  lat: number;
  lng: number;
  address: string;
  landmark?: string;
}

export interface AmbulanceInfo {
  id: string;
  driverName: string;
  vehicleNumber: string;
  contactNumber: string;
  currentLocation: {
    lat: number;
    lng: number;
  };
  estimatedArrival: string; // minutes
  status: 'available' | 'busy' | 'maintenance';
}

export interface HospitalInfo {
  id: string;
  name: string;
  address: string;
  distance: string;
  estimatedTime: string;
  erAvailable: boolean;
  bedsAvailable: number;
  icuBedsAvailable: number;
  phone: string;
  location: {
    lat: number;
    lng: number;
  };
}

export interface EmergencyRequest {
  id: string;
  patientId: string;
  patientName: string;
  patientPhone: string;
  emergencyType: EmergencyType;
  description: string;
  severity: 'critical' | 'high' | 'medium' | 'low';
  location: EmergencyLocation;
  status: EmergencyStatus;
  ambulanceId?: string;
  ambulance?: AmbulanceInfo;
  hospitalId?: string;
  hospital?: HospitalInfo;
  assignedDoctor?: string;
  vitalSigns?: {
    bloodPressure?: string;
    heartRate?: string;
    oxygenLevel?: string;
    temperature?: string;
  };
  timeline: {
    status: EmergencyStatus;
    timestamp: string;
    note?: string;
  }[];
  createdAt: string;
  updatedAt: string;
}

interface EmergencyState {
  requests: EmergencyRequest[];
  activeRequest: EmergencyRequest | null;
  nearbyHospitals: HospitalInfo[];
  availableAmbulances: AmbulanceInfo[];
  isLoading: boolean;
  isSubmitting: boolean;
  error: string | null;
  sosActivated: boolean;
  stats: {
    total: number;
    active: number;
    completed: number;
    avgResponseTime: string;
    todayCount: number;
  };
}

// ============================================
// INITIAL STATE
// ============================================

const initialState: EmergencyState = {
  requests: [],
  activeRequest: null,
  nearbyHospitals: [],
  availableAmbulances: [],
  isLoading: false,
  isSubmitting: false,
  error: null,
  sosActivated: false,
  stats: {
    total: 0,
    active: 0,
    completed: 0,
    avgResponseTime: '8 min',
    todayCount: 0,
  },
};

// ============================================
// ASYNC THUNKS
// ============================================

