// ============================================
// EMERGENCY SLICE
// ============================================

const emergencySlice = createSlice({
  name: 'emergency',
  initialState,
  reducers: {
    // Activate SOS mode
    activateSOS: (state) => {
      state.sosActivated = true;
    },

    // Deactivate SOS mode
    deactivateSOS: (state) => {
      state.sosActivated = false;
    },

    // Set active request
    setActiveRequest: (state, action: PayloadAction<EmergencyRequest | null>) => {
      state.activeRequest = action.payload;
    },

    // Add timeline event
    addTimelineEvent: (state, action: PayloadAction<{ id: string; status: EmergencyStatus; note?: string }>) => {
      const request = state.requests.find(r => r.id === action.payload.id);
      if (request) {
        request.timeline.push({
          status: action.payload.status,
          timestamp: new Date().toISOString(),
          note: action.payload.note,
        });
        request.status = action.payload.status;
      }
    },

    // Update ambulance tracking
    updateAmbulanceLocation: (state, action: PayloadAction<{ ambulanceId: string; location: { lat: number; lng: number }; estimatedArrival: string }>) => {
      const ambulance = state.availableAmbulances.find(a => a.id === action.payload.ambulanceId);
      if (ambulance) {
        ambulance.currentLocation = action.payload.location;
        ambulance.estimatedArrival = action.payload.estimatedArrival;
      }
    },

    // Clear error
    clearError: (state) => {
      state.error = null;
    },

    // Reset emergency state
    resetEmergencyState: () => initialState,
  },

  // ============================================
  // EXTRA REDUCERS
  // ============================================
  extraReducers: (builder) => {
    builder
      // Send SOS
      .addCase(sendEmergencySOS.pending, (state) => {
        state.isSubmitting = true;
        state.error = null;
      })
      .addCase(sendEmergencySOS.fulfilled, (state, action) => {
        state.isSubmitting = false;
        state.requests.unshift(action.payload);
        state.activeRequest = action.payload;
        state.sosActivated = true;
        state.stats.active += 1;
        state.stats.total += 1;
        state.stats.todayCount += 1;
      })
      .addCase(sendEmergencySOS.rejected, (state, action) => {
        state.isSubmitting = false;
        state.error = action.payload as string;
      })

      // Fetch Hospitals
      .addCase(fetchNearbyHospitals.pending, (state) => {
        state.isLoading = true;
      })
      .addCase(fetchNearbyHospitals.fulfilled, (state, action) => {
        state.isLoading = false;
        state.nearbyHospitals = action.payload;
      })
      .addCase(fetchNearbyHospitals.rejected, (state, action) => {
        state.isLoading = false;
        state.error = action.payload as string;
      })

      // Fetch Ambulances
      .addCase(fetchAvailableAmbulances.pending, (state) => {
        state.isLoading = true;
      })
      .addCase(fetchAvailableAmbulances.fulfilled, (state, action) => {
        state.isLoading = false;
        state.availableAmbulances = action.payload;
      })
      .addCase(fetchAvailableAmbulances.rejected, (state, action) => {
        state.isLoading = false;
        state.error = action.payload as string;
      })

      // Cancel Emergency
      .addCase(cancelEmergency.pending, (state) => {
        state.isSubmitting = true;
      })
      .addCase(cancelEmergency.fulfilled, (state, action) => {
        state.isSubmitting = false;
        const request = state.requests.find(r => r.id === action.payload);
        if (request) {
          request.status = 'cancelled';
          request.timeline.push({
            status: 'cancelled',
            timestamp: new Date().toISOString(),
            note: 'Emergency cancelled by user',
          });
          state.stats.active = Math.max(0, state.stats.active - 1);
        }
        if (state.activeRequest?.id === action.payload) {
          state.activeRequest = null;
          state.sosActivated = false;
        }
      })
      .addCase(cancelEmergency.rejected, (state, action) => {
        state.isSubmitting = false;
        state.error = action.payload as string;
      })

      // Update Status
      .addCase(updateEmergencyStatus.pending, (state) => {
        state.isLoading = true;
      })
      .addCase(updateEmergencyStatus.fulfilled, (state, action) => {
        state.isLoading = false;
        const request = state.requests.find(r => r.id === action.payload.id);
        if (request) {
          request.status = action.payload.status;
          request.timeline.push({
            status: action.payload.status,
            timestamp: new Date().toISOString(),
            note: action.payload.note,
          });
          
          if (action.payload.status === 'completed') {
            state.stats.active = Math.max(0, state.stats.active - 1);
            state.stats.completed += 1;
            state.sosActivated = false;
            state.activeRequest = null;
          }
        }
      })
      .addCase(updateEmergencyStatus.rejected, (state, action) => {
        state.isLoading = false;
        state.error = action.payload as string;
      });
  },
});

// ============================================
// ACTIONS
// ============================================

export const {
  activateSOS,
  deactivateSOS,
  setActiveRequest,
  addTimelineEvent,
  updateAmbulanceLocation,
  clearError,
  resetEmergencyState,
} = emergencySlice.actions;

// ============================================
// SELECTORS
// ============================================

export const selectAllEmergencyRequests = (state: { emergency: EmergencyState }) => state.emergency.requests;
export const selectActiveRequest = (state: { emergency: EmergencyState }) => state.emergency.activeRequest;
export const selectNearbyHospitals = (state: { emergency: EmergencyState }) => state.emergency.nearbyHospitals;
export const selectAvailableAmbulances = (state: { emergency: EmergencyState }) => state.emergency.availableAmbulances;
export const selectEmergencyLoading = (state: { emergency: EmergencyState }) => state.emergency.isLoading;
export const selectEmergencySubmitting = (state: { emergency: EmergencyState }) => state.emergency.isSubmitting;
export const selectEmergencyError = (state: { emergency: EmergencyState }) => state.emergency.error;
export const selectSOSActivated = (state: { emergency: EmergencyState }) => state.emergency.sosActivated;
export const selectEmergencyStats = (state: { emergency: EmergencyState }) => state.emergency.stats;

export const selectActiveEmergencies = (state: { emergency: EmergencyState }) => 
  state.emergency.requests.filter(r => 
    r.status !== 'completed' && r.status !== 'cancelled'
  );

export const selectCriticalEmergencies = (state: { emergency: EmergencyState }) =>
  state.emergency.requests.filter(r => r.severity === 'critical' && r.status !== 'completed');

// ============================================
// REDUCER
// ============================================

export default emergencySlice.reducer;

// src/store/slices/hospitalSlice.ts
// HOSPITAL STATE MANAGEMENT

import { createSlice, PayloadAction } from '@reduxjs/toolkit';

// ============================================
// TYPES
// ============================================

export interface HospitalProfile {
  id: string;
  name: string;
  registrationNumber: string;
  type: 'government' | 'private' | 'charitable';
  phone: string;
  emergencyPhone: string;
  email: string;
  address: {
    street: string;
    city: string;
    state: string;
    zipCode: string;
    country: string;
  };
  totalBeds: number;
  availableBeds: number;
  icuTotalBeds: number;
  icuAvailableBeds: number;
  emergencyServiceStatus: 'active' | 'busy' | 'unavailable';
  ambulanceCount: number;
  ambulanceAvailable: number;
  rating: number;
  isVerified: boolean;
}

export interface BedInfo {
  id: string;
  hospitalId: string;
  type: 'general' | 'icu' | 'emergency' | 'pediatric' | 'maternity';
  total: number;
  available: number;
  occupied: number;
  costPerDay: number;
}

export interface BloodStock {
  bloodGroup: string;
  units: number;
  status: 'sufficient' | 'low' | 'critical' | 'out-of-stock';
}

export interface HospitalStats {
  todayPatients: number;
  newAdmissions: number;
  discharges: number;
  emergencies: number;
  surgeries: number;
  occupancyRate: number;
}

export interface HospitalState {
  profile: HospitalProfile | null;
  bedInfo: BedInfo[];
  bloodStock: BloodStock[];
  stats: HospitalStats | null;
  doctors: any[];
  departments: any[];
  isLoading: boolean;
  error: string | null;
}

// ============================================
// INITIAL STATE
// ============================================

const initialState: HospitalState = {
  profile: null,
  bedInfo: [],
  bloodStock: [],
  stats: null,
  doctors: [],
  departments: [],
  isLoading: false,
  error: null,
};

// ============================================
// SLICE
// ============================================

const hospitalSlice = createSlice({
  name: 'hospital',
  initialState,
  reducers: {
    // Profile
    setHospitalProfile: (state, action: PayloadAction<HospitalProfile>) => {
      state.profile = action.payload;
    },
    updateHospitalProfile: (state, action: PayloadAction<Partial<HospitalProfile>>) => {
      if (state.profile) {
        state.profile = { ...state.profile, ...action.payload };
      }
    },

    // Beds
    setBedInfo: (state, action: PayloadAction<BedInfo[]>) => {
      state.bedInfo = action.payload;
    },
    updateBedAvailability: (state, action: PayloadAction<{ bedId: string; available: number; occupied: number }>) => {
      state.bedInfo = state.bedInfo.map(bed =>
        bed.id === action.payload.bedId
          ? { ...bed, available: action.payload.available, occupied: action.payload.occupied }
          : bed
      );
    },

    // Blood Stock
    setBloodStock: (state, action: PayloadAction<BloodStock[]>) => {
      state.bloodStock = action.payload;
    },
    updateBloodStock: (state, action: PayloadAction<{ bloodGroup: string; units: number }>) => {
      state.bloodStock = state.bloodStock.map(bs =>
        bs.bloodGroup === action.payload.bloodGroup
          ? { ...bs, units: action.payload.units }
          : bs
      );
    },

    // Stats
    setHospitalStats: (state, action: PayloadAction<HospitalStats>) => {
      state.stats = action.payload;
    },

    // Doctors
    setDoctors: (state, action: PayloadAction<any[]>) => {
      state.doctors = action.payload;
    },
    addDoctor: (state, action: PayloadAction<any>) => {
      state.doctors.push(action.payload);
    },
    removeDoctor: (state, action: PayloadAction<string>) => {
      state.doctors = state.doctors.filter(d => d.id !== action.payload);
    },

    // Departments
    setDepartments: (state, action: PayloadAction<any[]>) => {
      state.departments = action.payload;
    },

    // Emergency Status
    setEmergencyStatus: (state, action: PayloadAction<'active' | 'busy' | 'unavailable'>) => {
      if (state.profile) {
        state.profile.emergencyServiceStatus = action.payload;
      }
    },

    // Loading & Error
    setLoading: (state, action: PayloadAction<boolean>) => {
      state.isLoading = action.payload;
    },
    setError: (state, action: PayloadAction<string | null>) => {
      state.error = action.payload;
    },

    // Reset
    clearHospital: () => initialState,
  },
});

export const {
  setHospitalProfile, updateHospitalProfile,
  setBedInfo, updateBedAvailability,
  setBloodStock, updateBloodStock,
  setHospitalStats, setDoctors, addDoctor, removeDoctor,
  setDepartments, setEmergencyStatus,
  setLoading, setError, clearHospital,
} = hospitalSlice.actions;

export default hospitalSlice.reducer;

