  | 'picked-up' 
  | 'at-hospital' 
  | 'completed' 
  | 'cancelled';

export interface EmergencyLocation {
  lat: number;
  lng: number;
  address: string;
  landmark?: string;
}

export interface AmbulanceInfo {
  id: string;
  driverName: string;
  vehicleNumber: string;
  contactNumber: string;
  currentLocation: {
