export interface Doctor {
  id: string;
  name: string;
  specialty: string;
  rating: number;
  experience: number;
  image?: string;
  availability: string;
  fee: number;
  languages: string[];
  location: string;
  verified: boolean;
  specialties: string[];
  education: string;
  reviewsCount: number;
  nextSlot: string;
}

export interface DoctorFilters {
  specialty?: string;
  minRating?: number;
  maxFee?: number;
  searchQuery?: string;
  location?: string;
}

export interface DoctorState {
  doctors: Doctor[];
  filteredDoctors: Doctor[];
  selectedDoctor: Doctor | null;
  filters: DoctorFilters;
  specialties: string[];
  isLoading: boolean;
  error: string | null;
}

