      state.filters = action.payload;
      state.filteredDoctors = applyFilters(state.doctors, action.payload);
    },
    updateFilters: (state, action: PayloadAction<Partial<DoctorFilters>>) => {
      state.filters = { ...state.filters, ...action.payload };
