// ============================================
// TYPES
// ============================================

export type EmergencyType = 
  | 'cardiac' 
  | 'accident' 
  | 'stroke' 
  | 'breathing' 
  | 'bleeding' 
  | 'allergy' 
  | 'pregnancy' 
  | 'other';

export type EmergencyStatus = 
  | 'pending' 
  | 'dispatched' 
  | 'en-route' 
  | 'arrived' 
  | 'picked-up' 
  | 'at-hospital' 
  | 'completed' 
  | 'cancelled';

export interface EmergencyLocation {
  lat: number;
  lng: number;
